<template>
  <q-page class="q-pa-md">
    <div class="row">
      <div class="col-12">
        <q-card>
          <q-card-section>
            <div class="text-h6">🔧 PWA Cache Diagnostic Page</div>
            <div class="text-caption text-grey">For debugging blank screen issues</div>
          </q-card-section>

          <q-separator />

          <q-card-section>
            <div class="text-subtitle1 q-mb-md">📊 Cache Status</div>

            <div class="row q-col-gutter-md">
              <!-- Service Worker Status -->
              <div class="col-12 col-md-6">
                <q-card flat bordered class="bg-light">
                  <q-card-section>
                    <div class="text-weight-bold">Service Worker</div>
                    <div class="q-mt-md">
                      <div class="row q-col-gutter-sm">
                        <div class="col-6">
                          <strong>Available:</strong>
                        </div>
                        <div class="col-6">
                          <q-badge :color="diagnostics.hasServiceWorker ? 'positive' : 'negative'">
                            {{ diagnostics.hasServiceWorker ? '✓ Yes' : '✗ No' }}
                          </q-badge>
                        </div>
                      </div>

                      <div class="row q-col-gutter-sm q-mt-sm">
                        <div class="col-6">
                          <strong>Registrations:</strong>
                        </div>
                        <div class="col-6">{{ diagnostics.registrations }}</div>
                      </div>
                    </div>
                  </q-card-section>
                </q-card>
              </div>

              <!-- Version Status -->
              <div class="col-12 col-md-6">
                <q-card flat bordered class="bg-light">
                  <q-card-section>
                    <div class="text-weight-bold">Version</div>
                    <div class="q-mt-md">
                      <div class="row q-col-gutter-sm">
                        <div class="col-6">
                          <strong>Current:</strong>
                        </div>
                        <div class="col-6">{{ diagnostics.appVersion }}</div>
                      </div>

                      <div class="row q-col-gutter-sm q-mt-sm">
                        <div class="col-6">
                          <strong>Stored:</strong>
                        </div>
                        <div class="col-6">{{ diagnostics.storedVersion || 'Not set' }}</div>
                      </div>

                      <div class="row q-col-gutter-sm q-mt-sm">
                        <div class="col-6">
                          <strong>Mismatch:</strong>
                        </div>
                        <div class="col-6">
                          <q-badge :color="diagnostics.versionMismatch ? 'warning' : 'positive'">
                            {{ diagnostics.versionMismatch ? '⚠️ Yes' : '✓ No' }}
                          </q-badge>
                        </div>
                      </div>
                    </div>
                  </q-card-section>
                </q-card>
              </div>

              <!-- Cache Names -->
              <div class="col-12">
                <q-card flat bordered class="bg-light">
                  <q-card-section>
                    <div class="text-weight-bold">Cached Items ({{ diagnostics.cacheNames.length }})</div>
                    <div class="q-mt-md">
                      <div v-if="diagnostics.cacheNames.length === 0" class="text-grey">
                        No caches found
                      </div>
                      <div v-else>
                        <div
                          v-for="(cacheName, index) in diagnostics.cacheNames"
                          :key="index"
                          class="q-my-sm text-mono text-caption"
                        >
                          <q-badge color="primary">{{ index + 1 }}</q-badge> {{ cacheName }}
                        </div>
                      </div>
                    </div>
                  </q-card-section>
                </q-card>
              </div>
            </div>
          </q-card-section>

          <q-separator />

          <q-card-section>
            <div class="text-subtitle1 q-mb-md">⚙️ Actions</div>

            <div class="row q-col-gutter-md">
              <div class="col-12 col-md-6">
                <q-btn
                  unelevated
                  color="primary"
                  label="🔄 Reload Page"
                  size="md"
                  @click="reloadPage"
                  class="full-width"
                />
              </div>

              <div class="col-12 col-md-6">
                <q-btn
                  unelevated
                  color="warning"
                  label="🗑️ Clear All Caches"
                  size="md"
                  @click="clearCaches"
                  class="full-width"
                />
              </div>

              <div class="col-12 col-md-6">
                <q-btn
                  unelevated
                  color="negative"
                  label="🚫 Unregister Service Workers"
                  size="md"
                  @click="unregisterSW"
                  class="full-width"
                />
              </div>

              <div class="col-12 col-md-6">
                <q-btn
                  unelevated
                  color="info"
                  label="🆘 Emergency Cleanup"
                  size="md"
                  @click="emergencyCleanup"
                  class="full-width"
                />
              </div>
            </div>
          </q-card-section>

          <q-card-section class="bg-orange-1">
            <div class="text-caption text-orange-9">
              <strong>⚠️ Warning:</strong> These tools are for debugging only. Use Emergency Cleanup only if you're
              experiencing a blank screen issue.
            </div>
          </q-card-section>
        </q-card>
      </div>
    </div>
  </q-page>
</template>

<script setup>
import { notify } from 'src/components/notifications/notify';
import { ref, onMounted } from 'vue';
import { pwaCacheManager } from 'src/utils/pwaCache';

import logger from 'src/utils/logger';

const diagnostics = ref({
  hasServiceWorker: false,
  registrations: 0,
  cacheNames: [],
  appVersion: '',
  storedVersion: '',
  versionMismatch: false,
});

onMounted(async () => {
  await loadDiagnostics();
});

async function loadDiagnostics() {
  diagnostics.value = await pwaCacheManager.getDiagnostics();
}

function reloadPage() {
  window.location.reload();
}

async function clearCaches() {
  notify.info('Clearing all caches...');

  try {
    await pwaCacheManager.clearAllCaches();
    await loadDiagnostics();

    notify.success('Caches cleared successfully');
  } catch (error) {
    logger.error('Error clearing caches:', error);
    notify.error('Failed to clear caches');
  }
}

async function unregisterSW() {
  notify.info('Unregistering Service Workers...');

  try {
    await pwaCacheManager.unregisterServiceWorkers();
    await loadDiagnostics();

    notify.success('Service Workers unregistered');
  } catch (error) {
    logger.error('Error unregistering Service Workers:', error);
    notify.error('Failed to unregister Service Workers');
  }
}

async function emergencyCleanup() {
  notify.warning('Performing emergency cleanup. Page will reload...', { duration: 3000 });

  try {
    await pwaCacheManager.performFullCleanup();

    setTimeout(() => {
      window.location.reload();
    }, 1500);
  } catch (error) {
    logger.error('Error during emergency cleanup:', error);
    notify.error('Emergency cleanup failed');
  }
}
</script>

